  d = 2 * d;
  p = 2 * p;
}

while (1)
{
  if (!(A == ((q * B) + r)))
    break;
  d = d / 2;
  p = p / 2;
  if (r >= d)
  {
    r = r - d;
    q = q + p;
  }
}

return 0;
}


